    async detectEmotionForVoiceCall(text, appId) {
        try {
            const psychologicalDesc = this.extractPsychologicalDescription(text);
            if (psychologicalDesc) {
                common_1.Logger.debug(`[VoiceCall情绪识别] 提取到心理描述: ${psychologicalDesc}`, 'ChatService');
            }
            const options = await this.getAppEmotionOptionsRaw(appId);
            const pairs = await this.getAppEmotionPairsRaw(appId);
            common_1.Logger.debug(`[VoiceCall情绪识别] 应用情绪选项: ${options.join(', ') || '无'}`, 'ChatService');
            if (options.length === 0) {
                common_1.Logger.warn(`[VoiceCall情绪识别] 应用未配置情绪，使用默认`, 'ChatService');
                return null;
            }
            const chosen = await this.chooseEmotionFromOptionsRaw(psychologicalDesc, text, options);
            if (!chosen) {
                const fallback = await this.getAppDefaultEmotionRaw(appId, options);
                common_1.Logger.debug(`[VoiceCall情绪识别] 使用默认情绪: ${fallback}`, 'ChatService');
                const mappedVoice = pairs.find(p => p.emotion === fallback)?.voiceId;
                if (mappedVoice) {
                    return { emotion: fallback, voiceId: mappedVoice, method: 'default' };
                }
                return null;
            }
            const mappedVoice = pairs.find(p => p.emotion === chosen.emotion)?.voiceId;
            if (!mappedVoice) {
                common_1.Logger.warn(`[VoiceCall情绪识别] 情绪"${chosen.emotion}"未配置音色`, 'ChatService');
                return null;
            }
            common_1.Logger.debug(`[VoiceCall情绪识别] ✓ 识别成功: emotion=${chosen.emotion}, voiceId=${mappedVoice}, method=${chosen.method}`, 'ChatService');
            return {
                emotion: chosen.emotion,
                voiceId: mappedVoice,
                method: chosen.method,
            };
        }
        catch (error) {
            common_1.Logger.error(`[VoiceCall情绪识别] 识别失败: ${error?.message}`, error?.stack || '', 'ChatService');
            return null;
        }
    }
    async getAppEmotionOptionsRaw(appId) {
        if (!appId)
            return [];
        try {
            const rows = await this.appEmotionVoiceRepo.find({
                where: { appId: Number(appId), status: 1 },
            });
            const list = rows
                .filter(r => !!r.voiceId && !!r.emotion)
                .map(r => r.emotion.trim())
                .filter(e => !!e);
            return Array.from(new Set(list));
        }
        catch {
            return [];
        }
    }
    async getAppEmotionPairsRaw(appId) {
        const pairs = [];
        if (!appId)
            return pairs;
        try {
            const rows = await this.appEmotionVoiceRepo.find({
                where: { appId: Number(appId), status: 1 },
            });
            for (const r of rows) {
                if (!r.voiceId || !r.emotion)
                    continue;
                const emo = r.emotion.trim();
                if (!emo)
                    continue;
                if (pairs.find(p => p.emotion === emo))
                    continue;
                pairs.push({ emotion: emo, voiceId: r.voiceId });
            }
        }
        catch { }
        return pairs;
    }
    async getAppDefaultEmotionRaw(appId, options) {
        if (appId) {
            try {
                const def = await this.appVoiceRepo.findOne({
                    where: { appId: Number(appId), isDefault: 1 },
                });
                const defVoice = def?.voiceId || '';
                if (defVoice) {
                    const rec = await this.appEmotionVoiceRepo.findOne({
                        where: { appId: Number(appId), voiceId: defVoice, status: 1 },
                    });
                    const emo = rec?.emotion?.trim() || '';
                    if (emo && options.includes(emo))
                        return emo;
                }
            }
            catch { }
        }
        return options[0] || '默认';
    }
